package chunkstore

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"testing"
	"time"

	"github.com/cockroachdb/pebble"
)

// Prepare incrementally with -count=1. The seed is generated by whisperio's
// TestPrepareExpirationContentionSeed. IDs and catalog names have different
// order, and every fourth metric remains active during expiration.
func TestPrepareExpirationContentionStore(t *testing.T) {
	dir := os.Getenv("EXPIRATION_CONTENTION_DIR")
	if dir == "" {
		t.Skip("set EXPIRATION_CONTENTION_DIR, EXPIRATION_CONTENTION_SEED and EXPIRATION_CONTENTION_ADD")
	}
	count, err := strconv.Atoi(os.Getenv("EXPIRATION_CONTENTION_ADD"))
	if err != nil || count < 1 || count > 65536 {
		t.Fatal("add must be 1..65536")
	}
	data, err := os.ReadFile(os.Getenv("EXPIRATION_CONTENTION_SEED"))
	if err != nil {
		t.Fatal(err)
	}
	var seed TransferMetric
	if err := json.Unmarshal(data, &seed); err != nil || !seed.Continuation || len(seed.Keys) == 0 {
		t.Fatalf("invalid continuation seed: %v", err)
	}
	// This writer only copies the seed's physical keys. Measured operations
	// use the real continuation codec; preparation never calls this stand-in.
	s, err := Open(dir, Options{ExactBlocks: true, TimeBuckets: true, Continuation: bucketCodec{}, CacheSize: 64 << 20, MemTableSize: 64 << 20, SyncInterval: time.Hour, CompactionWorkers: 2})
	if err != nil {
		t.Fatal(err)
	}
	defer closeTestStore(t, s)
	ctx := context.Background()
	first, err := s.CatalogHighWatermark(ctx)
	if err != nil {
		t.Fatal(err)
	}
	m := Metadata{MetricConfig: seed.Config, Continuation: true, Generation: 1, Revision: 1}
	for offset := 0; offset < count; {
		batch := s.db.NewBatch()
		for range min(128, count-offset) {
			offset++
			m.ID = first + uint64(offset)
			m.Name = fmt.Sprintf("services.api.pods.pod%010d.requests", m.ID*15485863%4294967296)
			m.LastUpdate = time.Unix(1790000000-48*3600, 0)
			if m.ID%4 == 0 {
				m.LastUpdate = time.Unix(1790000000, 0)
			}
			catalog, err := s.encodeCatalog(m)
			if err != nil {
				t.Fatal(err)
			}
			if err := batch.Set(catalogKey(m.Name), catalog, nil); err != nil {
				t.Fatal(err)
			}
			if err := batch.Set(revisionKey(m), revisionBytes(m), nil); err != nil {
				t.Fatal(err)
			}
			io := s.newContinuationIO(ctx, nil, batch, m)
			for _, kv := range seed.Keys {
				if err := io.Set(kv.Key, kv.Value); err != nil {
					t.Fatal(err)
				}
			}
			io.Close()
		}
		if err := batch.Set(sequenceKey(), uint64Bytes(m.ID), nil); err != nil {
			t.Fatal(err)
		}
		if err := batch.Commit(pebble.NoSync); err != nil {
			t.Fatal(err)
		}
		batch.Close()
	}
	if err := s.Compact(); err != nil {
		t.Fatal(err)
	}
	t.Logf("prepared %d metrics, %d data keys/metric", first+uint64(count), len(seed.Keys))
}
